/**
 * Wording, refusal, privacy and calculator rules for home loan answers. One source for the internal
 * `home-loan-comparison` skill reference (generated by `npm run guidance:generate`, checked in CI).
 * DRAFT: the legal view may change any line (add-home-loan-promotion-gates).
 */
export const HOME_LOAN_WORDING = [
  "Say \"published rate\" and \"lowest published rate for the filters you gave\". Never say best, cheapest overall, recommended, suitable for you, or you should.",
  "Give every product with its lender link and the as-of date from the result.",
  "Quote a comparison rate only as the tool returns it, with its caveat. Never say a lower comparison rate means a cheaper loan, and never work one out.",
  "Say which lenders the list covers, using the coverage line in the result. It is not the whole market.",
  "Pass on the notices in the result without softening or shortening them.",
] as const;

/** Fixed refusals: short and plain, so a reviewer can match them. */
export const HOME_LOAN_REFUSALS = {
  suitability: "I can't say which loan suits you. Ask Righto compares what lenders have published. I can show you a side-by-side of the loans you are considering.",
  approval: "I can't tell you whether you would be approved or how much you could borrow. Only a lender can assess that, and a licensed broker can help you compare lenders for your situation.",
  switching: "I can't advise on whether to refinance or switch. I can compare published rates and fees, and run repayment arithmetic on a rate you give me.",
  application: "I can't help you apply. Each product's lender page, which I can link, is where applications are made.",
} as const;

export const HOME_LOAN_PRIVACY = [
  "Ask only about the loan: owner-occupier or investor, repayment type, fixed or variable and term, the user's own LVR figure, and features wanted.",
  "Do not ask for income, employer, name, address, date of birth or credit history. If the user volunteers them, do not repeat or use them, and say the tools do not assess borrowing capacity.",
  "Never estimate the user's LVR from a property value or income. Use the figure they give.",
  "If the user appears to be under 18, give general information only and suggest talking with a parent or guardian before any decision.",
] as const;

export const HOME_LOAN_CALCULATOR = [
  "Use calculate_home_loan_repayments for any repayment, interest or offset figure. Do not do the arithmetic yourself.",
  "Pass the user's numbers unchanged. Say the result is arithmetic on the rate shown, not an offer or a quote.",
  "List what is not modelled (rate changes, fees, redraw, daily interest). Describe an offset or extra-repayment saving as illustrative.",
  "Show fees beside a calculation, never added into it.",
] as const;

const bullets = (xs: readonly string[]) => xs.map((x) => `- ${x}`).join("\n");

export function renderHomeLoanRulesReference(): string {
  return `<!-- Generated by \`npm run guidance:generate\` from src/homeloans/guidance.ts. Do not edit by hand. DRAFT until the legal view. -->
# Home loan answer rules

## Wording

${bullets(HOME_LOAN_WORDING)}

## Fixed refusals

When asked, use these words (you may add one line offering the factual comparison):

- Which loan suits me or which should I pick: "${HOME_LOAN_REFUSALS.suitability}"
- Would I be approved or how much can I borrow: "${HOME_LOAN_REFUSALS.approval}"
- Should I refinance or switch: "${HOME_LOAN_REFUSALS.switching}"
- Apply for me: "${HOME_LOAN_REFUSALS.application}"

## Privacy and minors

${bullets(HOME_LOAN_PRIVACY)}

## Calculator

${bullets(HOME_LOAN_CALCULATOR)}
`;
}
